// Startet die Verbindung eines persoenlichen Microsoft-Kontos.
// Aufruf: /webhook/ms-connect?user=<kennung>&back=<optionale Rueckkehr-URL>
// Die Kennung kommt vom Aufrufer (Weboberflaeche oder Agent), NICHT vom Modell.
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };

const q = $input.first().json.query || {};
const userKey = String(q.user || '').trim();
const back = String(q.back || '').trim();

function page(title, text) {
  return { html: '<!doctype html><meta charset="utf-8"><title>' + title + '</title>' +
    '<style>body{font-family:system-ui,sans-serif;max-width:34rem;margin:4rem auto;padding:0 1rem;color:#1c2833}h1{font-size:1.3rem;color:#14532d}</style>' +
    '<h1>' + title + '</h1><p>' + text + '</p>' };
}

if (!userKey) {
  return [{ json: Object.assign({ error: true }, page('Verbindung nicht moeglich', 'Es fehlt die Angabe, fuer wen das Konto verbunden werden soll.')) }];
}

// Zugangsdaten der Anwendung
const credRows = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true
});
const cred = {};
for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
for (const need of ['tenant_id', 'client_id', 'redirect_uri']) {
  if (!cred[need]) {
    return [{ json: Object.assign({ error: true }, page('Nicht eingerichtet', 'In der Konfiguration fehlt: ' + need)) }];
  }
}

const SCOPES = cred.scopes || 'openid profile email offline_access User.Read Calendars.ReadWrite Mail.ReadWrite MailboxSettings.Read';

// state: einmalig, kurzlebig, an die Person gebunden. Ohne diese Bindung liesse
// sich der Rueecklaeufer niemandem zuordnen, genau das war die Luecke im
// bisherigen Google-Callback.
// Die Spalte ist eine UUID mit Vorgabewert, deshalb legt die Datenbank den Wert
// an und wir lesen ihn zurueck. Ein selbst gebauter String scheitert dort.
let state;
try {
  const ins = await helpers.httpRequest({
    method: 'POST',
    url: SUPABASE_URL + '/rest/v1/oauth_states',
    headers: Object.assign({ 'Prefer': 'return=representation' }, pg),
    body: JSON.stringify({
      template_id: 'microsoft', provider: 'microsoft',
      scopes: SCOPES, user_key: userKey, redirect_to: back || null
    }),
    json: true
  });
  state = ins && ins[0] && ins[0].state;
} catch (e) {
  const d = (e && e.response && e.response.body) ? JSON.stringify(e.response.body).slice(0, 300) : String(e.message || e);
  return [{ json: Object.assign({ error: true }, page('Vorgang nicht startbar', d)) }];
}
if (!state) {
  return [{ json: Object.assign({ error: true }, page('Vorgang nicht startbar', 'Die Datenbank lieferte keinen Vorgangsschluessel zurueck.')) }];
}

const url = 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/authorize' +
  '?client_id=' + encodeURIComponent(cred.client_id) +
  '&response_type=code&response_mode=query' +
  '&redirect_uri=' + encodeURIComponent(cred.redirect_uri) +
  '&scope=' + encodeURIComponent(SCOPES) +
  '&state=' + encodeURIComponent(state);

return [{ json: { error: false, url: url } }];

// Nimmt den Rueckl aeufer von Microsoft entgegen, tauscht den Code gegen Token
// und legt sie verschluesselt ab, gebunden an die Objekt-ID aus Entra.
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };

function page(title, text, ok) {
  return { html: '<!doctype html><meta charset="utf-8"><title>' + title + '</title>' +
    '<style>body{font-family:system-ui,sans-serif;max-width:34rem;margin:4rem auto;padding:0 1rem;color:#1c2833}' +
    'h1{font-size:1.3rem;color:' + (ok ? '#14532d' : '#8a2b2b') + '}</style>' +
    '<h1>' + title + '</h1><p>' + text + '</p>', ok: !!ok };
}

const q = $input.first().json.query || {};

if (q.error) {
  return [{ json: page('Verbindung abgebrochen', 'Microsoft meldet: ' + String(q.error_description || q.error).slice(0, 300), false) }];
}
if (!q.code || !q.state) {
  return [{ json: page('Unvollstaendige Antwort', 'Der Rueckl aeufer enthielt keinen Code.', false) }];
}

// 1. state pruefen: existiert, unbenutzt, nicht abgelaufen. Danach sofort
// entwerten, damit ein abgefangener Link nicht zweimal wirkt.
const rows = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/oauth_states?state=eq.' + encodeURIComponent(q.state) + '&select=*',
  headers: pg, json: true
});
const st = rows && rows[0];
if (!st) return [{ json: page('Unbekannter Vorgang', 'Dieser Verbindungslink gehoert zu keinem offenen Vorgang.', false) }];
if (st.used) return [{ json: page('Link bereits benutzt', 'Bitte den Vorgang neu starten.', false) }];
if (new Date(st.expires_at) < new Date()) return [{ json: page('Link abgelaufen', 'Bitte den Vorgang neu starten.', false) }];

await helpers.httpRequest({
  method: 'PATCH',
  url: SUPABASE_URL + '/rest/v1/oauth_states?state=eq.' + encodeURIComponent(q.state),
  headers: Object.assign({ 'Prefer': 'return=minimal' }, pg),
  body: JSON.stringify({ used: true })
});

// 2. Zugangsdaten der Anwendung
const credRows = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true
});
const cred = {};
for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
for (const need of ['tenant_id', 'client_id', 'client_secret', 'redirect_uri', 'token_key']) {
  if (!cred[need]) return [{ json: page('Nicht eingerichtet', 'In der Konfiguration fehlt: ' + need, false) }];
}

// 3. Code gegen Token tauschen
let tok;
try {
  const form = 'client_id=' + encodeURIComponent(cred.client_id) +
    '&client_secret=' + encodeURIComponent(cred.client_secret) +
    '&code=' + encodeURIComponent(q.code) +
    '&grant_type=authorization_code' +
    '&redirect_uri=' + encodeURIComponent(cred.redirect_uri) +
    '&scope=' + encodeURIComponent(st.scopes || '');
  tok = await helpers.httpRequest({
    method: 'POST',
    url: 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: form, json: true
  });
} catch (e) {
  const d = (e && e.response && e.response.body) ? JSON.stringify(e.response.body).slice(0, 400) : String(e.message || e);
  return [{ json: page('Token-Tausch fehlgeschlagen', d, false) }];
}
if (!tok || !tok.access_token) return [{ json: page('Token-Tausch fehlgeschlagen', 'Microsoft lieferte kein Zugriffstoken.', false) }];

// 4. Wer ist das? Die Objekt-ID ist der Schluessel, nicht die Mailadresse:
// Mail und Anmeldename sind laut Microsoft veraenderlich.
let me = {};
try {
  me = await helpers.httpRequest({
    method: 'GET', url: 'https://graph.microsoft.com/v1.0/me',
    headers: { Authorization: 'Bearer ' + tok.access_token }, json: true
  });
} catch (e) {
  return [{ json: page('Konto nicht lesbar', 'Das Zugriffstoken kam an, aber das Profil liess sich nicht abrufen.', false) }];
}
if (!me || !me.id) return [{ json: page('Konto nicht lesbar', 'Microsoft lieferte keine Objekt-ID.', false) }];

const entraKey = 'entra:' + me.id;

// 5. Verschluesselt ablegen. Die Verschluesselung passiert in der Datenbank-
// funktion, der Schluessel wird nur uebergeben und nirgends gespeichert.
const expiresAt = new Date(Date.now() + ((tok.expires_in || 3600) * 1000)).toISOString();
try {
  await helpers.httpRequest({
    method: 'POST',
    url: SUPABASE_URL + '/rest/v1/rpc/upsert_user_token',
    headers: pg,
    body: JSON.stringify({
      p_user_key: entraKey,
      p_provider: 'microsoft',
      p_key: cred.token_key,
      p_access_token: tok.access_token,
      p_refresh_token: tok.refresh_token || '',
      p_expires_at: expiresAt,
      p_scopes: tok.scope || st.scopes || null,
      p_account_id: me.id
    })
  });
} catch (e) {
  const d = (e && e.response && e.response.body) ? JSON.stringify(e.response.body).slice(0, 400) : String(e.message || e);
  return [{ json: page('Speichern fehlgeschlagen', d, false) }];
}

// 6. Verknuepfung festhalten: welche bisherige Kennung gehoert zu dieser Person.
// Ohne sie haengen Gedaechtnis und Verlauf weiter an der alten Kennung, waehrend
// die Microsoft-Werkzeuge unter der neuen arbeiten. Eigene Tabelle, damit nichts
// ueberschrieben wird, was der Agent ueber die Person gespeichert hat.
try {
  if (st.user_key && st.user_key !== entraKey) {
    await helpers.httpRequest({
      method: 'POST',
      url: SUPABASE_URL + '/rest/v1/user_identity_map?on_conflict=legacy_key',
      headers: Object.assign({ 'Prefer': 'resolution=merge-duplicates,return=minimal' }, pg),
      body: JSON.stringify({ legacy_key: st.user_key, entra_key: entraKey, entra_oid: me.id, upn: me.userPrincipalName || null })
    });
  }
} catch (e) {}

// 6b. Kam die Person ueber Teams (user_key ist schon der Entra-Schluessel), gibt es
// keine Verknuepfung zum Web-Profil. Dieselbe strenge Namensregel wie im
// Teams-Adapter: mindestens zwei Namenswoerter im Web-Profil, alle muessen im
// Microsoft-Namen vorkommen, genau ein Treffer, und der Web-Schluessel darf noch
// nicht anderweitig verknuepft sein.
try {
  if (!st.user_key || st.user_key === entraKey || String(st.user_key).startsWith('entra:')) {
    const normName = s => String(s || '').toLowerCase()
      .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
      .replace(/[,.;()]/g, ' ').split(/\s+/).filter(w => w.length > 1);
    const meWoerter = new Set(normName((me.givenName || '') + ' ' + (me.surname || '') + ' ' + (me.displayName || '')));
    if (meWoerter.size >= 2) {
      const profile = await helpers.httpRequest({ method: 'GET',
        url: SUPABASE_URL + '/rest/v1/user_profiles?user_id=like.web:*&select=user_id,display_name', headers: pg, json: true });
      const treffer = (Array.isArray(profile) ? profile : []).filter(p => {
        const w = normName(p.display_name);
        return w.length >= 2 && w.every(x => meWoerter.has(x));
      });
      if (treffer.length === 1) {
        const legacy = treffer[0].user_id;
        const belegt = await helpers.httpRequest({ method: 'GET',
          url: SUPABASE_URL + '/rest/v1/user_identity_map?legacy_key=eq.' + encodeURIComponent(legacy) + '&select=entra_key', headers: pg, json: true });
        if (!Array.isArray(belegt) || belegt.length === 0) {
          await helpers.httpRequest({ method: 'POST',
            url: SUPABASE_URL + '/rest/v1/user_identity_map?on_conflict=legacy_key',
            headers: Object.assign({ 'Prefer': 'resolution=ignore-duplicates,return=minimal' }, pg),
            body: JSON.stringify({ legacy_key: legacy, entra_key: entraKey, entra_oid: me.id, upn: me.userPrincipalName || null })
          });
        }
      }
    }
  }
} catch (e) {}

const name = (me.displayName || me.userPrincipalName || 'Konto');
return [{ json: page('Verbunden', 'Das Microsoft-Konto von ' + name + ' ist jetzt mit Rupert verbunden. Dieses Fenster kann geschlossen werden.', true) }];
